"""mtp-sampler: vllm-gaudi MTP draft-path changes recorded from the verified deployment

Generated from the verified deployment of GLM-5.3-Flash MTP speculative decoding
(docs/ports/glm-5-3-flash-mtp.md). Applies on top of the port image state: the
release fix profile (v0.26.0) and the port's own patches (install.sh) must already
be applied. Every replacement anchors exactly once; a mismatch writes nothing and
exits 2. Target: vllm_gaudi/v1/sample/hpu_rejection_sampler.py.

Usage: mtp_sampler.py [--check] [--root DIR_HOLDING_vllm_and_vllm_gaudi]
"""

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

from patchlib import main, replace_once

MARKER = "[gaudi-port:glm-5-3-flash/mtp-sampler]"

REPLACEMENTS = (
    ('\n\nrejection_sampler.rejection_sample = rejection_sample\n', '\n\nrejection_sampler.rejection_sample = rejection_sample\n\n\n# ---- [glm-5-mxfp4:spec-sampling] greedy + random rejection sampling ----\n# The HPU input batch stores greedy requests with temperature -1.0 (vLLM GPU: 0.0), so\n# "greedy" here means temperature < _HPU_SPEC_EPS (same rule as vLLM\'s Sampler).\n_HPU_SPEC_EPS = 1e-5\n\n\ndef _hpu_spec_expand_batch_to_tokens(x, cu_num_tokens, num_tokens, replace_from=0, replace_to=0):\n    # HPU layout: request i owns token rows i*k .. i*k+k-1, k = num_tokens // num_requests.\n    b = cu_num_tokens.shape[0]\n    xs = x[:b]\n    if xs.shape[0] < b:\n        xs = torch.cat([xs, xs[-1:].expand(b - xs.shape[0])])\n    mask = xs == replace_from\n    if replace_from == GREEDY_TEMPERATURE and replace_from != replace_to and xs.is_floating_point():\n        mask = mask | (xs < _HPU_SPEC_EPS)  # temperature call: HPU greedy rows are -1.0\n    xs = torch.where(mask, torch.full_like(xs, replace_to), xs)\n    k = max(1, num_tokens // b)\n    out = xs.repeat_interleave(k)\n    if out.shape[0] < num_tokens:\n        out = torch.cat([out, out[-1:].expand(num_tokens - out.shape[0])])\n    return out[:num_tokens]\n\n\ndef _hpu_spec_rejection_sample(draft_token_ids, num_draft_tokens, max_spec_len, cu_num_draft_tokens,\n                               draft_probs, target_probs, bonus_token_ids, sampling_metadata,\n                               synthetic_mode=False, synthetic_conditional_rates=None, use_fp64_gumbel=False):\n    # target_probs holds target LOGITS after temperature / top-k / top-p (upstream naming).\n    if sampling_metadata.all_greedy:\n        target_argmax = target_probs.argmax(dim=-1)\n        # Return on the logits\' device: RejectionSampler._get_logprobs_tensors indexes HPU logits with\n        # these ids, and a CPU tensor there kills the engine on any request that asks for logprobs.\n        return rejection_sample_pytorch(draft_token_ids, target_argmax, bonus_token_ids, num_draft_tokens,\n                                        cu_num_draft_tokens).to(target_probs.device)\n    assert draft_probs is None, "draft probabilities are not supported on HPU"\n    logits = target_probs.float()\n    n_rows = logits.shape[0]\n    n_req = len(num_draft_tokens)\n    k = max(1, n_rows // n_req)\n    draft = draft_token_ids.reshape(-1).to(torch.long)[:n_rows]\n    probs = logits.softmax(dim=-1)\n    p_draft = probs.gather(1, draft.unsqueeze(1)).squeeze(1)\n    argmax = logits.argmax(dim=-1)\n    # Gumbel-max over p_target with the draft token removed: argmax(p / E), E ~ Exp(1),\n    # one noise draw per request (only its first rejection is ever used).\n    e = torch.rand((n_req, probs.shape[1]), device=probs.device, dtype=torch.float32)\n    e = e.clamp_min_(1e-20).log_().neg_()\n    masked = probs.scatter(1, draft.unsqueeze(1), 0.0)\n    recovered = (masked / e.repeat_interleave(k, dim=0)[:n_rows]).argmax(dim=-1)\n    packed = torch.stack([p_draft, recovered.float(), argmax.float(), draft.float()]).cpu()\n    p_draft_c, rec_c, arg_c, draft_c = packed[0], packed[1].long(), packed[2].long(), packed[3].long()\n    bonus = bonus_token_ids.reshape(-1).cpu().to(torch.int32)\n    temp = sampling_metadata.temperature\n    if temp is not None and not sampling_metadata.all_random:\n        greedy = (temp[:n_req] < _HPU_SPEC_EPS).cpu().tolist()\n    else:\n        greedy = [False] * n_req\n    greedy = greedy + [False] * (n_req - len(greedy))\n    u = torch.rand(n_rows, dtype=torch.float64)\n    out = torch.full((n_req, k + 1), PLACEHOLDER_TOKEN_ID, dtype=torch.int32)\n    for i, n in enumerate(num_draft_tokens):\n        rejected = False\n        for j in range(n):\n            r = i * k + j\n            if greedy[i]:\n                tok = int(arg_c[r])\n                rejected = tok != int(draft_c[r])\n            elif float(p_draft_c[r]) >= float(u[r]) and float(p_draft_c[r]) > 0.0:\n                tok = int(draft_c[r])\n            else:\n                tok = int(rec_c[r])\n                rejected = True\n            out[i, j] = tok\n            if rejected:\n                break\n        if not rejected:\n            out[i, n] = int(bonus[i])\n    return out.to(target_probs.device)\n\n\nrejection_sampler.rejection_sample = _hpu_spec_rejection_sample\nrejection_sampler.expand_batch_to_tokens = _hpu_spec_expand_batch_to_tokens\n\n\n# ---- [glm-5-mxfp4:spec-penalties] logits processors on the HPU padded verify layout ----\nimport dataclasses as _hpu_dc\n\n_hpu_orig_rs_forward = rejection_sampler.RejectionSampler.forward\n_hpu_orig_rs_apply_lp = rejection_sampler.RejectionSampler.apply_logits_processors\n\n\ndef _hpu_spec_needs_lp(sm):\n    return (not sm.no_penalties) or bool(sm.bad_words_token_ids) or sm.allowed_token_ids_mask is not None\n\n\ndef _hpu_spec_draft_lists(metadata, pad_to_k):\n    n_req = len(metadata.num_draft_tokens)\n    flat = metadata.draft_token_ids.reshape(-1).tolist()\n    k = max(1, len(flat) // max(1, n_req))\n    out = []\n    for i, n in enumerate(metadata.num_draft_tokens):\n        row = [int(t) for t in flat[i * k:(i + 1) * k]]\n        n = int(n)\n        if pad_to_k:\n            out.append(row[:n] + [row[n - 1] if n > 0 else 0] * (k - n))\n        else:\n            out.append(row[:n])\n    return out, k\n\n\ndef _hpu_spec_rs_forward(self, metadata, draft_probs, logits, sampling_metadata):\n    if _hpu_spec_needs_lp(sampling_metadata) and sampling_metadata.spec_token_ids is None:\n        real, _ = _hpu_spec_draft_lists(metadata, pad_to_k=False)\n        sampling_metadata = _hpu_dc.replace(sampling_metadata, spec_token_ids=real)\n    return _hpu_orig_rs_forward(self, metadata, draft_probs, logits, sampling_metadata)\n\n\ndef _hpu_spec_rs_apply_lp(self, logits, sampling_metadata, metadata):\n    n_req = len(metadata.num_draft_tokens)\n    if n_req == 0 or not _hpu_spec_needs_lp(sampling_metadata):\n        return _hpu_orig_rs_apply_lp(self, logits, sampling_metadata, metadata)\n    k = logits.shape[0] // n_req\n    if k * n_req != logits.shape[0] or k < max(metadata.num_draft_tokens):\n        return _hpu_orig_rs_apply_lp(self, logits, sampling_metadata, metadata)  # not the HPU layout\n    padded, _ = _hpu_spec_draft_lists(metadata, pad_to_k=True)\n    md = _hpu_dc.replace(metadata, num_draft_tokens=[k] * n_req)\n    sm = _hpu_dc.replace(sampling_metadata, spec_token_ids=padded)\n    return _hpu_orig_rs_apply_lp(self, logits, sm, md)\n\n\nrejection_sampler.RejectionSampler.forward = _hpu_spec_rs_forward\nrejection_sampler.RejectionSampler.apply_logits_processors = _hpu_spec_rs_apply_lp\n', 'region@orig-line160'),  # noqa: E501
)


def patch(src: str) -> str:
    for old, new, label in REPLACEMENTS:
        src = replace_once(src, old, new, label)
    if MARKER not in src:
        src = src.rstrip("\n") + "\n\n# " + MARKER + "\n"
    return src


TARGETS = (("vllm_gaudi", "v1/sample/hpu_rejection_sampler.py", patch),)

if __name__ == "__main__":
    sys.exit(main(__doc__, MARKER, TARGETS))
